/*
 * @lc app=leetcode id=3435 lang=kotlin
 *
 * [3435] Frequencies of Shortest Supersequences
 */

class Solution {
    fun supersequences(words: Array<String>): List<List<Int>> = java.util.Optional.of(arrayOf(IntArray(26) { -1 }, IntArray(26), intArrayOf(0), arrayOfNulls<Any>(1), arrayOfNulls<Any>(1), intArrayOf(0))).map { st -> (0 until 26).forEach { i -> (st[0] as IntArray)[i] = -1 }.let { st } }.map { st -> words.forEach { w -> w.forEach { c -> if ((st[0] as IntArray)[c - 'a'] == -1) (st[0] as IntArray)[c - 'a'] = (st[2] as IntArray)[0]++ } }.let { st } }.map { st -> words.forEach { w -> (st[1] as IntArray)[(st[0] as IntArray)[w[1] - 'a']] = (st[1] as IntArray)[(st[0] as IntArray)[w[1] - 'a']] or (1 shl (st[0] as IntArray)[w[0] - 'a']) }.let { st } }.map { st -> (IntArray(1 shl (st[2] as IntArray)[0])).also { (st[3] as Array<Any?>)[0] = it }.let { st } }.map { st -> ({ mask: Int, bits: Int, self: (Int, Int) -> Int -> if (bits == 0) 0 else if (((st[1] as IntArray)[Integer.numberOfTrailingZeros(bits)] and mask) == 0 && ((st[3] as Array<Any?>)[0] as IntArray)[mask xor (1 shl Integer.numberOfTrailingZeros(bits))] == 1) 1 else self(mask, bits and (bits - 1)) }).let { f -> (st[4] as Array<Any?>)[0] = f }.let { st } }.map { st -> ((st[3] as Array<Any?>)[0] as IntArray)[0] = 1.let { (1 until (1 shl (st[2] as IntArray)[0])).forEach { m -> ((st[3] as Array<Any?>)[0] as IntArray)[m] = ((st[4] as Array<Any?>)[0] as (Int, Int, (Int, Int) -> Int) -> Int)(m, m, { a, b -> ((st[4] as Array<Any?>)[0] as (Int, Int, (Int, Int) -> Int) -> Int)(a, b, { c, d -> 0 }) }) }.let { st } } as Array<Any> }.map { st -> (st[5] as IntArray)[0] = (0 until (1 shl (st[2] as IntArray)[0])).filter { ((st[3] as Array<Any?>)[0] as IntArray)[it] == 1 }.maxOfOrNull { Integer.bitCount(it) } ?: 0.let { st } as Array<Any> }.map { st -> (0 until (1 shl (st[2] as IntArray)[0])).filter { ((st[3] as Array<Any?>)[0] as IntArray)[it] == 1 && Integer.bitCount(it) == (st[5] as IntArray)[0] }.map { m -> (0 until 26).map { c -> if ((st[0] as IntArray)[c] == -1) 0 else if (m and (1 shl (st[0] as IntArray)[c]) != 0) 1 else 2 } } }.get()
}